import React, { useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  CircularProgress,
  Stack,
  Typography,
} from '@mui/material';
import {
  AutoFixHigh as AutopilotIcon,
  Hub as HubIcon,
  PlayArrow as PlayArrowIcon,
  Psychology as AgentIcon,
} from '@mui/icons-material';
import ApiService from '../../services/api';
import OrchestrationRunPanel, { type OrchestrationRunSummary } from '../compliance/OrchestrationRunPanel';
import ReportGenerationStepper, { useStagedReportGeneration } from './ReportGenerationStepper';
import PipelinePartialFailureBanner from './PipelinePartialFailureBanner';
import { READINESS_ACTION_LABELS } from '../../constants/orchestrationUxLabels';
import { MSME_SIMPLIFIED_ACTION_LABELS } from '../../constants/msmeSimplifiedUi';
import useReadinessLocale from '../../hooks/useReadinessLocale';

export type ReportingAutomationPanelProps = {
  period?: string;
  exportApplicable?: boolean;
  onRefresh?: () => void;
  lastRun?: OrchestrationRunSummary | null;
  compact?: boolean;
};

const ReportingAutomationPanel: React.FC<ReportingAutomationPanelProps> = ({
  period = 'annual',
  exportApplicable = false,
  onRefresh,
  lastRun = null,
  compact = false,
}) => {
  const { strings } = useReadinessLocale();
  const [readinessRunning, setReadinessRunning] = useState(false);
  const [emissionsRunning, setEmissionsRunning] = useState(false);
  const [generateAllRunning, setGenerateAllRunning] = useState(false);
  const stagedGeneration = useStagedReportGeneration({ period, exportApplicable, profile: 'standard' });
  const [autopilotRunning, setAutopilotRunning] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [lastEmissionsRun, setLastEmissionsRun] = useState<OrchestrationRunSummary | null>(null);

  const runReadinessCheck = async () => {
    setReadinessRunning(true);
    setError(null);
    setFeedback(null);
    try {
      const res = await ApiService.orchestrateReportingReadiness({
        period,
        actionLimit: 8,
        runAutopilot: true,
        includeBrsrOrchestration: true,
        includeIsoOrchestration: true,
        includePcfOrchestration: exportApplicable,
        includeCbamOrchestration: exportApplicable,
      });
      const data = (res as { data?: { message?: string; overallReadinessScore?: number } })?.data;
      setFeedback(
        data?.message?.replace(/orchestration/gi, 'readiness check')
          || (data?.overallReadinessScore != null
            ? `Readiness check complete — overall ${Math.round(data.overallReadinessScore)}%.`
            : 'Readiness check complete.')
      );
      onRefresh?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Readiness check failed.');
    } finally {
      setReadinessRunning(false);
    }
  };

  const runEmissionsReporting = async () => {
    setEmissionsRunning(true);
    setError(null);
    setFeedback(null);
    try {
      const frameworks = ['BRSR', 'ISO14064', ...(exportApplicable ? ['CBAM'] : [])];
      const res = await ApiService.orchestrateEmissionsReporting({ period, frameworks });
      const data = (res as {
        data?: {
          reporting?: {
            overallReadinessScore?: number;
            agentPipeline?: OrchestrationRunSummary['stages'];
          };
        };
      })?.data;
      const score = data?.reporting?.overallReadinessScore;
      setFeedback(
        score != null
          ? `Emissions and reporting analysis finished — overall readiness ${Math.round(score)}%.`
          : 'Emissions and reporting analysis complete.'
      );
      setLastEmissionsRun({
        orchestratorType: 'emissions_reporting',
        success: true,
        stages: data?.reporting?.agentPipeline || [],
        lastRunAt: new Date().toISOString(),
      });
      onRefresh?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Emissions reporting analysis failed.');
    } finally {
      setEmissionsRunning(false);
    }
  };

  const runGenerateAll = async () => {
    setGenerateAllRunning(true);
    setError(null);
    setFeedback(null);
    try {
      const result = await stagedGeneration.runStandard();
      if (result.partialFailures?.length) {
        setFeedback(
          `Generated with ${result.partialFailures.length} issue(s) — review details below.`
        );
      } else {
        setFeedback(
          result.bundle?.summary?.message
            || `Generated ${result.bundle?.summary?.successCount ?? 0} reports${
              result.bundle?.summary?.failedCount
                ? ` (${result.bundle.summary.failedCount} failed)`
                : ''
            }.`
        );
      }
      onRefresh?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Full report generation failed.');
    } finally {
      setGenerateAllRunning(false);
    }
  };

  const runAutopilot = async () => {
    setAutopilotRunning(true);
    setError(null);
    setFeedback(null);
    try {
      const result = await ApiService.runComplianceHubAutopilot({
        period,
        applyChanges: true,
        runAgents: true,
      });
      const payload = (result as { data?: { closuresApplied?: unknown[]; documentVerifications?: unknown[] } })?.data;
      const closuresApplied = payload?.closuresApplied;
      const documentVerifications = payload?.documentVerifications;
      const closureCount = Array.isArray(closuresApplied) ? closuresApplied.length : 0;
      const docCount = Array.isArray(documentVerifications) ? documentVerifications.length : 0;
      setFeedback(
        closureCount || docCount
          ? `Auto-fix complete — ${docCount} document check(s), ${closureCount} update(s) applied.`
          : 'Auto-fix finished — no additional changes were needed.'
      );
      onRefresh?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Auto-fix failed.');
    } finally {
      setAutopilotRunning(false);
    }
  };

  const title = compact
    ? MSME_SIMPLIFIED_ACTION_LABELS.helpReportReady
    : READINESS_ACTION_LABELS.reportingAutomationTitle;
  const subtitle = compact
    ? MSME_SIMPLIFIED_ACTION_LABELS.helpReportReadyHint
    : READINESS_ACTION_LABELS.reportingAutomationSubtitle;

  return (
    <Card variant="outlined" sx={{ mb: 3 }}>
      <CardContent>
        <Stack spacing={2}>
          <Box>
            <Typography variant={compact ? 'subtitle1' : 'h6'} fontWeight={700} gutterBottom>
              {title}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 760 }}>
              {subtitle}
            </Typography>
          </Box>

          {feedback ? <Alert severity="success">{feedback}</Alert> : null}
          {error ? <Alert severity="error">{error}</Alert> : null}
          <PipelinePartialFailureBanner
            failures={stagedGeneration.partialFailures}
            onRetry={generateAllRunning || stagedGeneration.running ? undefined : runGenerateAll}
          />

          <ReportGenerationStepper
            running={generateAllRunning || stagedGeneration.running}
            stages={stagedGeneration.stages}
          />

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} flexWrap="wrap" useFlexGap alignItems="center">
            <Button
              variant="contained"
              disabled={readinessRunning}
              onClick={() => void runReadinessCheck()}
              startIcon={readinessRunning ? <CircularProgress size={18} color="inherit" /> : <PlayArrowIcon />}
            >
              {readinessRunning
                ? 'Checking…'
                : (compact ? MSME_SIMPLIFIED_ACTION_LABELS.checkReadiness : strings.checkReadiness)}
            </Button>

            {compact ? (
              <Button
                variant="text"
                disabled={autopilotRunning}
                onClick={() => void runAutopilot()}
                startIcon={autopilotRunning ? <CircularProgress size={14} /> : <AutopilotIcon />}
              >
                {autopilotRunning ? 'Matching…' : strings.matchBillsAutomatically}
              </Button>
            ) : (
              <>
                <Button
                  variant="outlined"
                  disabled={emissionsRunning}
                  onClick={() => void runEmissionsReporting()}
                  startIcon={emissionsRunning ? <CircularProgress size={16} /> : <AgentIcon />}
                >
                  {emissionsRunning ? 'Analyzing…' : READINESS_ACTION_LABELS.analyzeEmissionsForReports}
                </Button>
                <Button
                  variant="outlined"
                  color="secondary"
                  disabled={generateAllRunning || stagedGeneration.running}
                  onClick={() => void runGenerateAll()}
                  startIcon={(generateAllRunning || stagedGeneration.running) ? <CircularProgress size={16} color="inherit" /> : <HubIcon />}
                >
                  {(generateAllRunning || stagedGeneration.running) ? 'Generating…' : READINESS_ACTION_LABELS.orchestrateAllReports}
                </Button>
                <Button
                  variant="outlined"
                  disabled={autopilotRunning}
                  onClick={() => void runAutopilot()}
                  startIcon={autopilotRunning ? <CircularProgress size={16} /> : <AutopilotIcon />}
                >
                  {autopilotRunning ? 'Applying…' : strings.autoFixFromDocuments}
                </Button>
              </>
            )}
          </Stack>

          {!compact ? (
            <Typography variant="caption" color="text.secondary">
              {READINESS_ACTION_LABELS.analyzeEmissionsForReportsHint}{' '}
              {READINESS_ACTION_LABELS.orchestrateAllReportsHint}
            </Typography>
          ) : null}

          {!compact && lastRun ? (
            <OrchestrationRunPanel lastRun={lastRun} title="Last readiness check" compact />
          ) : null}
          {!compact && lastEmissionsRun ? (
            <OrchestrationRunPanel lastRun={lastEmissionsRun} title="Last emissions & reporting run" compact />
          ) : null}
        </Stack>
      </CardContent>
    </Card>
  );
};

export default ReportingAutomationPanel;
